const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const root = path.resolve(__dirname, '..');

function run(args) {
  return spawnSync(process.execPath, args, { cwd: root, encoding: 'utf8' });
}

test('list and existing export preserve complete records and order', () => {
  const listing = run(['cli.cjs', 'data.json', 'list']);
  assert.equal(listing.status, 0);
  assert.equal(listing.stderr, '');
  assert.equal(listing.stdout, JSON.stringify([
    { id: 't3', title: 'Review docs', status: 'open', owner: 'Ada' },
    { id: 't1', title: 'Ship parser', status: 'done', owner: 'Ada' },
    { id: 't4', title: 'Triage', status: 'open', owner: 'Lin' },
    { id: 't2', title: 'Check CLI', status: 'done', owner: 'Lin' },
    { id: 't5', title: 'No owner', status: 'open', owner: null },
    { id: 't6', title: 'Unicode café', status: 'open', owner: 'Ada Lovelace' }
  ]) + '\n');
  const exported = run(['export.cjs', 'data.json']);
  assert.equal(exported.status, 0);
  assert.equal(exported.stderr, '');
  assert.equal(exported.stdout, 't3,t1,t4,t2,t5,t6\n');
});

for (const { name, args, expected } of [
  {
    name: 'open status retains all matching records in source order',
    args: ['--status', 'open'],
    expected: [
      { id: 't3', title: 'Review docs', status: 'open', owner: 'Ada' },
      { id: 't4', title: 'Triage', status: 'open', owner: 'Lin' },
      { id: 't5', title: 'No owner', status: 'open', owner: null },
      { id: 't6', title: 'Unicode café', status: 'open', owner: 'Ada Lovelace' }
    ]
  },
  {
    name: 'done status retains matching records in source order',
    args: ['--status', 'done'],
    expected: [
      { id: 't1', title: 'Ship parser', status: 'done', owner: 'Ada' },
      { id: 't2', title: 'Check CLI', status: 'done', owner: 'Lin' }
    ]
  },
  {
    name: 'owner matches exactly without matching a longer name',
    args: ['--owner', 'Ada'],
    expected: [
      { id: 't3', title: 'Review docs', status: 'open', owner: 'Ada' },
      { id: 't1', title: 'Ship parser', status: 'done', owner: 'Ada' }
    ]
  },
  {
    name: 'owner accepts a name containing spaces',
    args: ['--owner', 'Ada Lovelace'],
    expected: [{ id: 't6', title: 'Unicode café', status: 'open', owner: 'Ada Lovelace' }]
  },
  {
    name: 'status and owner combine with AND',
    args: ['--status', 'done', '--owner', 'Ada'],
    expected: [{ id: 't1', title: 'Ship parser', status: 'done', owner: 'Ada' }]
  },
  {
    name: 'owner may precede status',
    args: ['--owner', 'Ada', '--status', 'done'],
    expected: [{ id: 't1', title: 'Ship parser', status: 'done', owner: 'Ada' }]
  },
  { name: 'a disjoint combination returns an empty array', args: ['--owner', 'Ada Lovelace', '--status', 'done'], expected: [] },
  { name: 'owner matching is case sensitive', args: ['--owner', 'ada'], expected: [] },
  { name: 'owner matching does not trim whitespace', args: ['--owner', ' Ada '], expected: [] },
  { name: 'an empty owner is a present exact value', args: ['--owner', ''], expected: [] }
]) {
  test(name, () => {
    const result = run(['cli.cjs', 'data.json', 'list', ...args]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(expected) + '\n');
  });
}

for (const { args, diagnostic } of [
  { args: ['--unknown', 'value'], diagnostic: /Unknown argument: --unknown/ },
  { args: ['--status=open'], diagnostic: /Unknown argument: --status=open/ },
  { args: ['extra'], diagnostic: /Unknown argument: extra/ },
  { args: ['--status', 'open', '--status', 'done'], diagnostic: /Repeated flag: --status/ },
  { args: ['--owner', 'Ada', '--owner', 'Lin'], diagnostic: /Repeated flag: --owner/ },
  { args: ['--owner', '', '--owner', 'Ada'], diagnostic: /Repeated flag: --owner/ },
  { args: ['--status'], diagnostic: /Missing value for --status/ },
  { args: ['--owner'], diagnostic: /Missing value for --owner/ },
  { args: ['--status', '--owner', 'Ada'], diagnostic: /Missing value for --status/ },
  { args: ['--owner', '--status', 'open'], diagnostic: /Missing value for --owner/ },
  { args: ['--status', 'closed'], diagnostic: /Invalid --status: expected open or done/ },
  { args: ['--status', 'OPEN'], diagnostic: /Invalid --status: expected open or done/ },
  { args: ['--status', ''], diagnostic: /Invalid --status: expected open or done/ }
]) {
  test(`invalid arguments fail without stdout: ${JSON.stringify(args)}`, () => {
    const result = run(['cli.cjs', 'data.json', 'list', ...args]);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, diagnostic);
  });
}

test('argument validation precedes opening the input file', () => {
  const result = run(['cli.cjs', 'missing-input.json', 'list', '--status', 'closed']);
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /Invalid --status: expected open or done/);
});

