/** @typedef {{ status?: 'open' | 'done', owner?: string }} TaskSelection */

function parseInvocation(argv) {
  const [file, command, ...args] = argv;
  if (!file || command !== 'list') {
    throw new Error('Usage: FILE list [--status open|done] [--owner NAME]');
  }
  /** @type {TaskSelection} */
  const selection = {};
  for (let i = 0; i < args.length; i += 2) {
    const flag = args[i];
    if (flag !== '--status' && flag !== '--owner') {
      throw new Error(`Unknown argument: ${flag}`);
    }
    const key = flag.slice(2);
    if (Object.hasOwn(selection, key)) {
      throw new Error(`Repeated flag: ${flag}`);
    }
    const value = args[i + 1];
    if (value === undefined || value.startsWith('--')) {
      throw new Error(`Missing value for ${flag}`);
    }
    if (flag === '--status' && value !== 'open' && value !== 'done') {
      throw new Error('Invalid --status: expected open or done');
    }
    selection[key] = value;
  }
  return { file, selection };
}

function selectTasks(rows, selection) {
  if (selection.status === undefined && selection.owner === undefined) return rows;
  return rows.filter(row =>
    (selection.status === undefined || row.status === selection.status) &&
    (selection.owner === undefined || row.owner === selection.owner)
  );
}

try {
  const { file, selection } = parseInvocation(process.argv.slice(2));
  process.stdout.write(JSON.stringify(selectTasks(list(file), selection)) + '\n');
} catch (error) {
  process.stderr.write(error.message + '\n');
  process.exitCode = 2;
