test/cli.test.cjs.text:
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const root = path.resolve(__dirname, '..');

function runList(args = [], file = 'data.json') {
  return spawnSync(process.execPath, ['cli.cjs', file, 'list', ...args], {cwd:root, encoding:'utf8'});
}

test('list and existing export preserve complete records and order', () => {
  const listing = runList();
  assert.equal(listing.status, 0);
  assert.equal(listing.stderr, '');
  assert.equal(listing.stdout, JSON.stringify([
    {id:'t3', title:'Review docs', status:'open', owner:'Ada'},
    {id:'t1', title:'Ship parser', status:'done', owner:'Ada'},
    {id:'t4', title:'Triage', status:'open', owner:'Lin'},
    {id:'t2', title:'Check CLI', status:'done', owner:'Lin'},
    {id:'t5', title:'No owner', status:'open', owner:null},
    {id:'t6', title:'Unicode café', status:'open', owner:'Ada Lovelace'},
  ]) + '\n');
  const exported = spawnSync(process.execPath, ['export.cjs', 'data.json'], {cwd:root, encoding:'utf8'});
  assert.equal(exported.status, 0);
  assert.equal(exported.stderr, '');
  assert.equal(exported.stdout, 't3,t1,t4,t2,t5,t6\n');
});

for (const [name, args, expected] of [
  ['open status', ['--status', 'open'], [
    {id:'t3', title:'Review docs', status:'open', owner:'Ada'},
    {id:'t4', title:'Triage', status:'open', owner:'Lin'},
    {id:'t5', title:'No owner', status:'open', owner:null},
    {id:'t6', title:'Unicode café', status:'open', owner:'Ada Lovelace'},
  ]],
  ['done status', ['--status', 'done'], [
    {id:'t1', title:'Ship parser', status:'done', owner:'Ada'},
    {id:'t2', title:'Check CLI', status:'done', owner:'Lin'},
  ]],
  ['exact owner', ['--owner', 'Ada'], [
    {id:'t3', title:'Review docs', status:'open', owner:'Ada'},
    {id:'t1', title:'Ship parser', status:'done', owner:'Ada'},
  ]],
  ['owner with spaces', ['--owner', 'Ada Lovelace'], [
    {id:'t6', title:'Unicode café', status:'open', owner:'Ada Lovelace'},
  ]],
  ['status and owner', ['--status', 'open', '--owner', 'Ada'], [
    {id:'t3', title:'Review docs', status:'open', owner:'Ada'},
  ]],
  ['owner and status', ['--owner', 'Ada', '--status', 'done'], [
    {id:'t1', title:'Ship parser', status:'done', owner:'Ada'},
  ]],
  ['no matching intersection', ['--owner', 'Ada Lovelace', '--status', 'done'], []],
  ['case-sensitive owner', ['--owner', 'ada'], []],
  ['owner whitespace is exact', ['--owner', ' Ada '], []],
  ['owner prefix does not match', ['--owner', 'Ad'], []],
  ['empty owner is a value', ['--owner', ''], []],
  ['null owner is not a string', ['--owner', 'null'], []],
]) {
  test(`list filters by ${name}`, () => {
    const result = runList(args);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(expected) + '\n');
  });
}

for (const [args, message] of [
  [['--other', 'x'], /Unknown argument.*--other/],
  [['extra'], /Unknown argument.*extra/],
  [['--status=open'], /Unknown argument.*--status=open/],
  [['--owner=Ada'], /Unknown argument.*--owner=Ada/],
  [['--'], /Unknown argument.*--/],
  [['--status', 'open', '--status', 'done'], /Repeated flag.*--status/],
  [['--owner', 'Ada', '--owner', 'Lin'], /Repeated flag.*--owner/],
  [['--owner', '', '--owner', 'Ada'], /Repeated flag.*--owner/],
  [['--status'], /Missing value.*--status/],
  [['--owner'], /Missing value.*--owner/],
  [['--status', '--owner', 'Ada'], /Missing value.*--status/],
  [['--owner', '--status', 'open'], /Missing value.*--owner/],
  [['--status', 'pending'], /Invalid --status.*open.*done/],
  [['--status', 'OPEN'], /Invalid --status.*open.*done/],
  [['--status', ''], /Invalid --status.*open.*done/],
]) {
  test(`rejects invalid arguments ${JSON.stringify(args)}`, () => {
    const result = runList(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, message);
  });
}

test('validates arguments before opening the input file', () => {
  const result = runList(['--status', 'pending'], 'missing-task-input.json');
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, 'Invalid --status: expected open or done\n');
});

